import { registerWebComponents } from '@domg-wc/common';
import { VlPropertiesComponent } from '@domg-wc/components/block';

registerWebComponents([VlPropertiesComponent]);

import { registerWebComponents } from '@domg-wc/common';
import { VlPropertiesComponent } from '@domg-wc/components/block';

registerWebComponents([VlPropertiesComponent]);

// props is een lijst van kolommen, elk met items van labels en data. vl-properties toont de props vóór wat in zijn
// inhoud staat: hier eerst Straat, daarna Woonplaats en Postcode.
document.querySelector('vl-properties').props = [
    {
        class: 'column',
        items: [{ labels: ['Straat'], data: ['Appelstraat', 'Perenstraat'] }],
    },
];

import { registerWebComponents } from '@domg-wc/common';
import { VlIconComponent } from '@domg-wc/components/atom';
import { VlPropertiesComponent } from '@domg-wc/components/block';

// vl-properties kopieert de inhoud naar zijn shadow DOM; registreer ook de componenten die erin staan.
registerWebComponents([VlPropertiesComponent, VlIconComponent]);
